#!/usr/bin/env python3
import base64, os, sys, shutil, json
from pathlib import Path
from datetime import datetime

def root():
    if sys.platform == "win32":
        return Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Documents" / "FXJEFE_Project"
    return Path.home() / "Documents" / "FXJEFE_Project"
FILES = {
  'feature_registry.py': b'',
  'runtime_lock.py': b'',
  'env.template': b'',
  'config.accept_all.json': b'',
}
r = root()
r.mkdir(parents=True, exist_ok=True)
for name, b64 in FILES.items():
    dest = r / name
    if name == "config.accept_all.json":
        dest = r / "config" / "config.accept_all.json"
        dest.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64)
    if dest.exists() and name.endswith(".py"):
        bak = dest.with_suffix(dest.suffix + ".bak_" + datetime.now().strftime("%Y%m%d%H%M%S"))
        shutil.copy2(dest, bak)
        print("backup", bak.name)
    dest.write_bytes(data)
    print("wrote", dest)
print("Running runtime_lock...")
import subprocess
raise SystemExit(subprocess.call([sys.executable, str(r / "runtime_lock.py")]))
